{
  "application": "poster-generation",
  "case_id": "case-culture-advocacy-feeding-america-hunger-crisis",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "portrait",
    "audience": "public-exhibition",
    "tone": "bold, warm",
    "venue": null
  },
  "brief": {
    "title": "Hunger Doesn't Wait — Together We Can End It",
    "one_liner": "48 million Americans face hunger, but a united network of food banks, volunteers, and advocates is fighting back with billions of meals every year.",
    "goal": "Inspire viewers to understand the scale of hunger in America and motivate them to take action — whether through donating, volunteering, advocating, or fundraising."
  },
  "sections": [
    {
      "id": "crisis-overview",
      "title": "The Hunger Crisis in America",
      "objective": "Present the scale of food insecurity across the U.S. with key statistics on affected populations, including children."
    },
    {
      "id": "network-impact",
      "title": "Our Collective Impact",
      "objective": "Showcase the measurable outcomes of the Feeding America network — meals distributed, food rescued, programs operated, and food banks mobilized."
    },
    {
      "id": "how-it-works",
      "title": "How We Unite Communities",
      "objective": "Explain the four pillars of the approach: research-driven insights, local relationships, nationwide scale, and nutrition-focused vision."
    },
    {
      "id": "take-action",
      "title": "How You Can Make a Difference",
      "objective": "Present clear calls to action — donate, advocate, fundraise, and volunteer — with a compelling reason for each."
    }
  ],
  "metrics": [
    {
      "label": "People Facing Hunger",
      "value": "48 million",
      "context": "across the United States"
    },
    {
      "label": "Children Affected",
      "value": "14 million",
      "context": "children face hunger in the U.S."
    },
    {
      "label": "Meals Distributed",
      "value": "5.7 billion",
      "context": "meals provided through the network"
    },
    {
      "label": "Food Rescued",
      "value": "4.3 billion pounds",
      "context": "of good food saved from waste"
    },
    {
      "label": "Programs Operating",
      "value": "60,000+",
      "context": "programs distributing free food"
    },
    {
      "label": "Food Banks in Network",
      "value": "200+",
      "context": "food banks nationwide"
    },
    {
      "label": "Donation Impact",
      "value": "$1 = 10 meals",
      "context": "every dollar provides at least 10 meals"
    }
  ]
}

