<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hunger Doesn't Wait - Advocacy Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600;700;800;900&family=Playfair+Display:wght@700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2400px;
    height: 3600px;
    background: #1a0f0a;
    font-family: 'Inter', sans-serif;
    color: #fef3e4;
    overflow: hidden;
  }

  .poster {
    width: 100%;
    height: 100%;
    background: linear-gradient(175deg, #1a0a02 0%, #2d1810 15%, #1a0f0a 30%, #1c0e05 50%, #1a0a02 100%);
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 120px 140px 100px 140px;
  }

  /* Subtle texture overlay */
  .poster::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse at 20% 10%, rgba(234, 88, 12, 0.08) 0%, transparent 50%),
      radial-gradient(ellipse at 80% 40%, rgba(217, 119, 6, 0.06) 0%, transparent 50%),
      radial-gradient(ellipse at 50% 85%, rgba(220, 38, 38, 0.06) 0%, transparent 50%);
    pointer-events: none;
  }

  /* ===== HERO SECTION ===== */
  .hero {
    position: relative;
    z-index: 1;
    margin-bottom: 80px;
  }

  .hero-eyebrow {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 52px;
    letter-spacing: 12px;
    color: #ea580c;
    text-transform: uppercase;
    margin-bottom: 24px;
  }

  .hero-title {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 240px;
    line-height: 0.88;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #fef3e4;
  }

  .hero-title .accent {
    color: #ea580c;
  }

  .hero-divider {
    width: 200px;
    height: 8px;
    background: linear-gradient(90deg, #ea580c, #f97316, #d97706);
    margin: 48px 0;
  }

  /* ===== STATS BANNER ===== */
  .stats-banner {
    position: relative;
    z-index: 1;
    display: flex;
    gap: 80px;
    margin-bottom: 100px;
    align-items: stretch;
  }

  .stat-card {
    flex: 1;
    background: rgba(254, 243, 228, 0.04);
    border: 2px solid rgba(234, 88, 12, 0.25);
    border-radius: 12px;
    padding: 60px 50px;
    position: relative;
    overflow: hidden;
  }

  .stat-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 6px;
  }

  .stat-card.crisis::before { background: linear-gradient(90deg, #dc2626, #ea580c); }
  .stat-card.children::before { background: linear-gradient(90deg, #ea580c, #f97316); }
  .stat-card.meals::before { background: linear-gradient(90deg, #f97316, #d97706); }

  .stat-number {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 160px;
    line-height: 0.9;
    letter-spacing: 1px;
  }

  .stat-card.crisis .stat-number { color: #ea580c; }
  .stat-card.children .stat-number { color: #f97316; }
  .stat-card.meals .stat-number { color: #d97706; }

  .stat-label {
    font-size: 36px;
    font-weight: 700;
    color: #fef3e4;
    margin-top: 20px;
    line-height: 1.2;
  }

  .stat-context {
    font-size: 28px;
    color: rgba(254, 243, 228, 0.6);
    margin-top: 10px;
    font-weight: 400;
  }

  /* ===== IMPACT STRIP ===== */
  .impact-strip {
    position: relative;
    z-index: 1;
    display: flex;
    gap: 60px;
    margin-bottom: 100px;
    flex-wrap: wrap;
    justify-content: center;
  }

  .impact-item {
    text-align: center;
    min-width: 280px;
  }

  .impact-value {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 100px;
    line-height: 1;
    background: linear-gradient(180deg, #fef3e4 0%, #ea580c 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .impact-desc {
    font-size: 28px;
    color: rgba(254, 243, 228, 0.7);
    margin-top: 8px;
    font-weight: 500;
  }

  /* ===== PILLARS ===== */
  .pillars {
    position: relative;
    z-index: 1;
    display: flex;
    gap: 50px;
    margin-bottom: 100px;
  }

  .pillar {
    flex: 1;
    text-align: center;
    padding: 50px 35px;
    background: rgba(254, 243, 228, 0.03);
    border-radius: 16px;
    border: 1px solid rgba(234, 88, 12, 0.15);
  }

  .pillar-icon {
    font-size: 64px;
    margin-bottom: 24px;
    filter: grayscale(0);
  }

  .pillar-title {
    font-size: 32px;
    font-weight: 800;
    color: #f97316;
    margin-bottom: 16px;
    line-height: 1.2;
    letter-spacing: 0.5px;
  }

  .pillar-desc {
    font-size: 24px;
    color: rgba(254, 243, 228, 0.6);
    line-height: 1.5;
  }

  /* ===== QUOTE ===== */
  .quote-section {
    position: relative;
    z-index: 1;
    margin-bottom: 100px;
    padding: 70px 100px;
    background: rgba(234, 88, 12, 0.06);
    border-left: 8px solid #ea580c;
    border-radius: 0 12px 12px 0;
  }

  .quote-text {
    font-family: 'Playfair Display', serif;
    font-size: 42px;
    font-weight: 700;
    line-height: 1.45;
    color: #fef3e4;
    font-style: italic;
  }

  .quote-text::before { content: '\201C'; color: #ea580c; }
  .quote-text::after { content: '\201D'; color: #ea580c; }

  .quote-attribution {
    font-size: 28px;
    color: #d97706;
    margin-top: 30px;
    font-weight: 600;
  }

  /* ===== CTA SECTION ===== */
  .cta-section {
    position: relative;
    z-index: 1;
    margin-bottom: 80px;
  }

  .cta-header {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 96px;
    color: #fef3e4;
    text-align: center;
    letter-spacing: 4px;
    margin-bottom: 60px;
  }

  .cta-grid {
    display: flex;
    gap: 50px;
  }

  .cta-card {
    flex: 1;
    padding: 55px 40px;
    border-radius: 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 2px solid rgba(254, 243, 228, 0.1);
  }

  .cta-card::before {
    content: '';
    position: absolute;
    inset: 0;
    opacity: 0.08;
  }

  .cta-card:nth-child(1) { background: rgba(234, 88, 12, 0.15); border-color: rgba(234, 88, 12, 0.4); }
  .cta-card:nth-child(2) { background: rgba(249, 115, 22, 0.12); border-color: rgba(249, 115, 22, 0.35); }
  .cta-card:nth-child(3) { background: rgba(217, 119, 6, 0.12); border-color: rgba(217, 119, 6, 0.35); }
  .cta-card:nth-child(4) { background: rgba(180, 83, 9, 0.12); border-color: rgba(180, 83, 9, 0.35); }

  .cta-icon {
    font-size: 72px;
    margin-bottom: 24px;
  }

  .cta-title {
    font-size: 48px;
    font-weight: 900;
    color: #fef3e4;
    margin-bottom: 16px;
    letter-spacing: 1px;
  }

  .cta-desc {
    font-size: 26px;
    color: rgba(254, 243, 228, 0.7);
    line-height: 1.4;
    font-weight: 500;
  }

  /* ===== DONATION IMPACT BADGE ===== */
  .donation-badge {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 40px;
    padding: 50px;
    background: linear-gradient(135deg, rgba(234, 88, 12, 0.2), rgba(217, 119, 6, 0.15));
    border: 3px solid rgba(234, 88, 12, 0.5);
    border-radius: 20px;
    margin-bottom: 60px;
  }

  .donation-number {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 120px;
    color: #f97316;
    line-height: 1;
  }

  .donation-text {
    font-size: 40px;
    font-weight: 700;
    color: #fef3e4;
    line-height: 1.3;
  }

  .donation-sub {
    font-size: 28px;
    color: rgba(254, 243, 228, 0.6);
    margin-top: 6px;
  }

  /* ===== FOOTER ===== */
  .footer {
    position: relative;
    z-index: 1;
    text-align: center;
    margin-top: auto;
    padding-top: 40px;
  }

  .footer-text {
    font-family: 'Bebas Neue', sans-serif;
    font-size: 52px;
    color: rgba(254, 243, 228, 0.5);
    letter-spacing: 8px;
    text-transform: uppercase;
  }
</style>
</head>
