node -e "
const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(3000);

  // Check font loading status
  const fontInfo = await page.evaluate(() => {
    const fonts = document.fonts;
    const results = [];
    fonts.forEach(f => results.push({ family: f.family, status: f.status }));
    return results;
  });
  console.log('Fonts loaded:', JSON.stringify(fontInfo, null, 2));

  // Check for any console errors
  page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await browser.close();
})();
" 2>&1

arguments.content:
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Force all fonts to load
  await page.evaluate(async () => {
    await document.fonts.ready;
    // Force-load all used font families
    await Promise.all([
      document.fonts.load('240px "Bebas Neue"'),
      document.fonts.load('160px "Bebas Neue"'),
      document.fonts.load('100px "Bebas Neue"'),
      document.fonts.load('56px Inter'),
      document.fonts.load('42px "Playfair Display"'),
      document.fonts.load('bold 36px Inter'),
      document.fonts.load('bold 28px Inter'),
    ]);
  });

  // Allow rendering to settle
  await page.waitForTimeout(3000);

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png'
  });

  console.log('Poster rendered to /app/output/final_poster.png');
  await browser.close();
})();

