  await page.evaluate(async () => {
    await document.fonts.ready;
    // Force-load all used font families
    await Promise.all([
      document.fonts.load('240px "Bebas Neue"'),
      document.fonts.load('160px "Bebas Neue"'),
      document.fonts.load('100px "Bebas Neue"'),
      document.fonts.load('56px Inter'),
      document.fonts.load('42px "Playfair Display"'),
      document.fonts.load('bold 36px Inter'),
      document.fonts.load('bold 28px Inter'),
    ]);
  });

  // Allow rendering to settle
  await page.waitForTimeout(3000);

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png'
  });

  console.log('Poster rendered to /app/output/final_poster.png');
  await browser.close();
})();

